use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let arr = input.as_array().unwrap();
    let left: Vec<(i64, i64)> = arr[0]
        .as_array()
        .unwrap()
        .iter()
        .map(|pair| {
            let pair_arr = pair.as_array().unwrap();
            (pair_arr[0].as_i64().unwrap(), pair_arr[1].as_i64().unwrap())
        })
        .collect();
    let right: Vec<(i64, i64)> = arr[1]
        .as_array()
        .unwrap()
        .iter()
        .map(|pair| {
            let pair_arr = pair.as_array().unwrap();
            (pair_arr[0].as_i64().unwrap(), pair_arr[1].as_i64().unwrap())
        })
        .collect();

    let mut result = Vec::new();
    let mut left_iter = left.iter();
    let mut right_iter = right.iter();

    let mut left_key = left_iter.next().map(|&(k, _)| k);
    let mut right_key = right_iter.next().map(|&(k, _)| k);

    while left_key.is_some() || right_key.is_some() {
        let key = match (left_key, right_key) {
            (Some(lk), Some(rk)) => if lk < rk { lk } else { rk },
            (Some(lk), None) => lk,
            (None, Some(rk)) => rk,
            (None, None) => unreachable!(),
        };

        if let Some(&(l_key, l_value)) = left_iter.as_ref().and_then(|iter| iter.find(|&&(k, _)| k == key)) {
            if let Some(&(r_key, r_value)) = right_iter.as_ref().and_then(|iter| iter.find(|&&(k, _)| k == key)) {
                result.push(json!([key, l_value, r_value]));
            }
        }

        if left_key == Some(key) {
            left_key = left_iter.next().map(|&(k, _)| k);
        }
        if right_key == Some(key) {
            right_key = right_iter.next().map(|&(k, _)| k);
        }
    }

    json!(result)
}
